UPDATE issues SET status = 'closed', closed_by = #{closedBy}, closed_at = CURRENT_TIMESTAMP,
    updated_by = #{closedBy}, updated_at = CURRENT_TIMESTAMP
WHERE id = #{id} AND updated_at = #{expectedUpdatedAt}

UPDATE issues SET status = 'new', closed_by = NULL, closed_at = NULL,
    updated_by = #{updatedBy}, updated_at = CURRENT_TIMESTAMP
WHERE id = #{id} AND updated_at = #{expectedUpdatedAt}
